use crate::aap::caps::inference_llm::infer;

struct Node;

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // Precondition (requires len(value.text) <= 4000) is a graph-level
        // guarantee about the input; we do not re-derive it here. We only
        // make sure our *output* satisfies every `ensures`.
        let text = message.text;

        // Ask the model to label the intent. The closed `Intent` enum has no
        // "other" case, so whatever the model (or adversarial text) says, the
        // value we can construct is always one of the five permitted labels:
        // the intent `ensures` is discharged by the type, not by trusting the
        // model's string.
        let intent_raw = infer(
            "You classify a customer support message into exactly one intent. \
             Reply with only one of these labels and nothing else: \
             billing_question, technical_support, account_change, \
             general_inquiry, unknown.",
            &text,
            "classify",
        );
        let intent = parse_intent(&intent_raw);

        // Extract a single concise question. We clamp the result to 512
        // characters so `ensures len(question) <= 512` holds regardless of
        // what the model returns.
        let question_raw = infer(
            "Restate the customer's core question as a single concise sentence. \
             Output only that sentence, 512 characters or fewer.",
            &text,
            "classify",
        );
        let question = clamp_chars(&question_raw, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

/// Map arbitrary model output onto the closed intent set. Any unrecognised
/// response collapses to `Unknown`, which keeps the output inside the
/// permitted set by construction.
fn parse_intent(s: &str) -> Intent {
    let t = s.trim().to_ascii_lowercase();
    // Prefer exact-label matches; fall back to keyword heuristics.
    if t == "billing_question" || t.contains("billing") {
        Intent::BillingQuestion
    } else if t == "technical_support" || t.contains("technical") || t.contains("support") {
        Intent::TechnicalSupport
    } else if t == "account_change" || t.contains("account") {
        Intent::AccountChange
    } else if t == "general_inquiry" || t.contains("general") || t.contains("inquiry") {
        Intent::GeneralInquiry
    } else {
        Intent::Unknown
    }
}

/// Trim and truncate to at most `max` Unicode scalar values, matching Python's
/// character-counting `len` so the `ensures` bound is enforced the same way.
fn clamp_chars(s: &str, max: usize) -> String {
    s.trim().chars().take(max).collect()
}

export!(Node);
